export function lighten(hex, amt = 0.25) {
  const c = parseHex(hex);
  return `rgb(${Math.min(255, Math.round(c[0] + (255 - c[0]) * amt))},${Math.min(255, Math.round(c[1] + (255 - c[1]) * amt))},${Math.min(255, Math.round(c[2] + (255 - c[2]) * amt))})`;
}
export function darken(hex, amt = 0.3) {
  const c = parseHex(hex);
  return `rgb(${Math.max(0, Math.round(c[0] * (1 - amt)))},${Math.max(0, Math.round(c[1] * (1 - amt)))},${Math.max(0, Math.round(c[2] * (1 - amt)))})`;
}
export function parseHex(hex) {
  const h = String(hex || '#888888').replace('#', '');
  const full = h.length === 3 ? h.split('').map(x => x + x).join('') : h.padEnd(6, '0').slice(0, 6);
  const n = parseInt(full, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
export function rgba(hex, a = 1) {
  const c = parseHex(hex);
  return `rgba(${c[0]},${c[1]},${c[2]},${a})`;
}

import {
  CARS, CARS_BY_ID, CARS_BY_RARITY, PACKS_BY_ID, RARITIES, RARITY_ORDER, TRACKS_BY_ID,
  TRAITS, WHEEL_REWARDS, WHEEL_COST, FREE_SPIN_MS, MAX_LEVEL, upgradeCost, carDisplayStats,
} from './data.js';

const SAVE_KEY = 'apexrip_save_v2';
const SAVE_VERSION = 2;
const listeners = new Set();

const clamp = (v, min, max) => Math.max(min, Math.min(max, v));
const num = (v, fallback, min = 0, max = Number.MAX_SAFE_INTEGER) => {
  const n = Number(v);
  return Number.isFinite(n) ? clamp(n, min, max) : fallback;
};
const int = (v, fallback, min = 0, max = 1000000) => Math.round(num(v, fallback, min, max));
const safeId = (v, allowed) => (typeof v === 'string' && allowed.includes(v) ? v : allowed[0]);

function blankLevels() { return { speed: 0, accel: 0, grip: 0 }; }

function freshState() {
  const now = Date.now();
  return {
    version: SAVE_VERSION,
    credits: 1500,
    scraps: 0,
    fusionCores: 0,
    blueprints: {},
    owned: { 'civic-ghost': blankLevels() },
    selectedCar: 'civic-ghost',
    selectedPack: 'midnight-circuit',
    selectedTrack: 'midnight-touge',
    autoRip: false,
    lastSeen: now,
    pendingOffline: 0,
    wheel: { lastFree: 0, lastSpin: 0 },
    races: {},
    stats: { pulls: 0, races: 0, wins: 0, spins: 0, fusions: 0 },
    settings: { sound: true },
  };
}

function sanitizeLevels(raw) {
  const src = raw && typeof raw === 'object' ? raw : {};
  return {
    speed: int(src.speed, 0, 0, MAX_LEVEL),
    accel: int(src.accel, 0, 0, MAX_LEVEL),
    grip: int(src.grip, 0, 0, MAX_LEVEL),
  };
}

function sanitize(raw) {
  const base = freshState();
  if (!raw || typeof raw !== 'object') return base;

  const owned = {};
  if (raw.owned && typeof raw.owned === 'object' && !Array.isArray(raw.owned)) {
    for (const [id, lv] of Object.entries(raw.owned)) {
      if (CARS_BY_ID[id]) owned[id] = sanitizeLevels(lv);
    }
  }
  // A save that has pulled before but somehow lost its cars should not brick progression.
  if (!Object.keys(owned).length && raw.owned && int(raw.stats?.pulls, 0) === 0) {
    owned['civic-ghost'] = blankLevels();
  }

  const blueprints = {};
  if (raw.blueprints && typeof raw.blueprints === 'object') {
    for (const [id, n] of Object.entries(raw.blueprints)) {
      if (CARS_BY_ID[id]) {
        const count = int(n, 0, 0, 9999);
        if (count > 0) blueprints[id] = count;
      }
    }
  }

  const races = {};
  if (raw.races && typeof raw.races === 'object') {
    for (const [id, t] of Object.entries(raw.races)) {
      if (TRACKS_BY_ID[id] && Number.isFinite(Number(t)) && Number(t) > 0) {
        races[id] = Math.min(Number(t), 3600);
      }
    }
  }

  const ownedIds = Object.keys(owned);
  const selectedCar = ownedIds.includes(raw.selectedCar) ? raw.selectedCar : (ownedIds[0] || 'civic-ghost');

  const wheelRaw = raw.wheel && typeof raw.wheel === 'object' ? raw.wheel : {};
  const now = Date.now();
  const lastSeen = num(raw.lastSeen, now, 0, now + 60000);

  return {
    version: SAVE_VERSION,
    credits: int(raw.credits, 1500, 0, 999999999),
    scraps: int(raw.scraps, 0, 0, 9999999),
    fusionCores: int(raw.fusionCores, 0, 0, 9999),
    blueprints,
    owned,
    selectedCar,
    selectedPack: PACKS_BY_ID[raw.selectedPack] ? raw.selectedPack : base.selectedPack,
    selectedTrack: TRACKS_BY_ID[raw.selectedTrack] ? raw.selectedTrack : base.selectedTrack,
    autoRip: raw.autoRip === true,
    lastSeen,
    pendingOffline: num(raw.pendingOffline, 0, 0, 5000),
    wheel: {
      lastFree: num(wheelRaw.lastFree, 0, 0, now + 86400000),
      lastSpin: num(wheelRaw.lastSpin, 0, 0, now + 86400000),
    },
    races,
    stats: {
      pulls: int(raw.stats?.pulls, 0, 0, 9999999),
      races: int(raw.stats?.races, 0, 0, 9999999),
      wins: int(raw.stats?.wins, 0, 0, 9999999),
      spins: int(raw.stats?.spins, 0, 0, 9999999),
      fusions: int(raw.stats?.fusions, 0, 0, 9999999),
    },
    settings: {
      sound: raw.settings?.sound !== false,
    },
  };
}

export class Store {
  constructor() {
    this.state = freshState();
    this.lastError = '';
    this._hiddenAt = 0;
    this._lastSave = 0;
    this.load();
  }

  load() {
    let raw = null;
    try {
      const text = localStorage.getItem(SAVE_KEY);
      if (text) raw = JSON.parse(text);
    } catch (err) {
      this.lastError = 'Save was unreadable; starting with a clean garage.';
      raw = null;
    }
    const now = Date.now();
    this.state = sanitize(raw);
    if (raw && this.state.lastSeen > 0) {
      const mins = clamp((now - this.state.lastSeen) / 60000, 0, 480);
      this.state.pendingOffline = clamp(this.state.pendingOffline + mins * this.passiveRate(), 0, this.offlineCap());
    }
    this.state.lastSeen = now;
    this.save(true);
  }

  save(force = false) {
    const now = Date.now();
    if (!force && now - this._lastSave < 400) return;
    this._lastSave = now;
    this.state.lastSeen = now;
    try {
      localStorage.setItem(SAVE_KEY, JSON.stringify(this.state));
    } catch (err) {
      this.lastError = 'Could not write save data.';
    }
  }

  reset() {
    try { localStorage.removeItem(SAVE_KEY); } catch {}
    this.state = freshState();
    this.save(true);
    this.emit('reset');
  }

  subscribe(fn) { listeners.add(fn); return () => listeners.delete(fn); }
  emit(type = 'change', payload = null) {
    for (const fn of listeners) {
      try { fn(type, payload, this.state); } catch (err) { console.error(err); }
    }
  }

  // ── Derived helpers ───────────────────────────────────────────────────────
  levels(carId) { return this.state.owned[carId] || blankLevels(); }
  isOwned(carId) { return Boolean(this.state.owned[carId]); }
  displayStats(car) { return carDisplayStats(car, this.levels(car.id)); }
  blueprintCount(carId) { return this.state.blueprints[carId] || 0; }
  ownedCount() { return Object.keys(this.state.owned).length; }
  passiveRate() {
    const n = this.ownedCount();
    return Math.round((0.4 + n * 0.32) * 100) / 100;
  }
  offlineCap() { return 900; }
  offlinePending() { return Math.max(0, Math.round(this.state.pendingOffline || 0)); }

  lineup() {
    return Object.keys(this.state.owned)
      .map(id => CARS_BY_ID[id])
      .filter(Boolean)
      .sort((a, b) => {
        const ra = RARITIES[a.rarity].tier;
        const rb = RARITIES[b.rarity].tier;
        if (rb !== ra) return rb - ra;
        return this.power(b.id) - this.power(a.id);
      })
      .slice(0, 6);
  }

  power(carId) {
    const car = CARS_BY_ID[carId];
    if (!car) return 0;
    const s = this.displayStats(car);
    return s.speed + s.accel + s.grip;
  }

  bestCar() {
    const ids = Object.keys(this.state.owned).filter(id => CARS_BY_ID[id]);
    if (!ids.length) return null;
    ids.sort((a, b) => (RARITIES[CARS_BY_ID[b].rarity].tier - RARITIES[CARS_BY_ID[a].rarity].tier) || (this.power(b) - this.power(a)));
    return CARS_BY_ID[ids[0]];
  }

  selectedCar() {
    const id = this.state.selectedCar;
    if (id && this.state.owned[id]) return CARS_BY_ID[id];
    return this.bestCar();
  }

  setSelectedCar(id) {
    if (this.state.owned[id]) {
      this.state.selectedCar = id;
      this.save();
      this.emit('selected');
    }
  }
  setSelectedPack(id) {
    if (PACKS_BY_ID[id]) { this.state.selectedPack = id; this.save(); this.emit('selected'); }
  }
  setSelectedTrack(id) {
    if (TRACKS_BY_ID[id]) { this.state.selectedTrack = id; this.save(); this.emit('selected'); }
  }
  toggleAutoRip() {
    this.state.autoRip = !this.state.autoRip;
    this.save();
    this.emit('selected');
    return this.state.autoRip;
  }
  toggleSound() {
    this.state.settings.sound = !this.state.settings.sound;
    this.save();
    this.emit('settings');
    return this.state.settings.sound;
  }

  // ── Pack ripping ──────────────────────────────────────────────────────────
  canBuy(packId) {
    const pack = PACKS_BY_ID[packId];
    return Boolean(pack && this.state.credits >= pack.price);
  }

  pull(packId) {
    const pack = PACKS_BY_ID[packId];
    if (!pack) return { ok: false, reason: 'Unknown pack.' };
    if (this.state.credits < pack.price) return { ok: false, reason: 'Not enough credits.' };

    this.state.credits -= pack.price;
    this.state.stats.pulls += 1;

    // Weighted rarity roll.
    let roll = Math.random() * 100;
    let rarity = 'stock';
    for (let i = 0; i < RARITY_ORDER.length; i++) {
      roll -= pack.odds[i];
      if (roll <= 0) { rarity = RARITY_ORDER[i]; break; }
    }

    let pool = CARS_BY_RARITY[rarity] || CARS;
    if (!pool.length) pool = CARS;
    const focusPool = pool.filter(c => pack.focus.includes(c.id));
    const car = (focusPool.length && Math.random() < 0.55)
      ? focusPool[Math.floor(Math.random() * focusPool.length)]
      : pool[Math.floor(Math.random() * pool.length)];

    const rarityDef = RARITIES[car.rarity];
    let isNew = false;
    let blueprints = 0;
    let scraps = 0;
    if (!this.state.owned[car.id]) {
      isNew = true;
      this.state.owned[car.id] = blankLevels();
      this.state.selectedCar = car.id;
    } else {
      blueprints = 1 + (Math.random() < rarityDef.tier * 0.06 ? 1 : 0);
      scraps = 2 + Math.floor(Math.random() * (rarityDef.tier + 2));
      this.state.blueprints[car.id] = this.blueprintCount(car.id) + blueprints;
      this.state.scraps += scraps;
    }

    this.save(true);
    this.emit('pull', { car, isNew, blueprints, scraps, pack });
    return { ok: true, car, isNew, blueprints, scraps, pack, rarity: car.rarity };
  }

  // ── Upgrades / fusion / vault ─────────────────────────────────────────────
  upgrade(carId, stat) {
    if (!['speed', 'accel', 'grip'].includes(stat)) return { ok: false, reason: 'Unknown stat.' };
    const car = CARS_BY_ID[carId];
    if (!car || !this.state.owned[carId]) return { ok: false, reason: 'Car not owned.' };
    const lv = this.state.owned[carId][stat];
    if (lv >= MAX_LEVEL) return { ok: false, reason: 'Already maxed.' };
    const cost = upgradeCost(lv);
    if (this.state.credits < cost) return { ok: false, reason: 'Not enough credits.' };
    const hasBp = this.blueprintCount(carId) > 0;
    const hasCore = this.state.fusionCores > 0;
    if (!hasBp && !hasCore) return { ok: false, reason: 'Need a blueprint or fusion core.' };

    this.state.credits -= cost;
    if (hasBp) this.state.blueprints[carId] -= 1;
    else this.state.fusionCores -= 1;
    if (this.state.blueprints[carId] <= 0) delete this.state.blueprints[carId];
    this.state.owned[carId][stat] = lv + 1;
    this.state.selectedCar = carId;
    this.save(true);
    this.emit('upgrade', { car, stat, level: lv + 1, cost });
    return { ok: true, level: lv + 1, cost, usedCore: !hasBp };
  }

  fuse(carId) {
    const car = CARS_BY_ID[carId];
    if (!car) return { ok: false, reason: 'Unknown car.' };
    if (this.blueprintCount(carId) < 3) return { ok: false, reason: 'Need 3 blueprints.' };
    if (this.state.scraps < 20) return { ok: false, reason: 'Need 20 scraps.' };
    this.state.blueprints[carId] -= 3;
    if (this.state.blueprints[carId] <= 0) delete this.state.blueprints[carId];
    this.state.scraps -= 20;
    this.state.fusionCores += 1;
    this.state.stats.fusions += 1;
    this.save(true);
    this.emit('fusion', { car, cores: this.state.fusionCores });
    return { ok: true };
  }

  scrapBlueprint(carId) {
    const car = CARS_BY_ID[carId];
    if (!car) return { ok: false, reason: 'Unknown car.' };
    const count = this.blueprintCount(carId);
    if (count < 1) return { ok: false, reason: 'No blueprints.' };
    const amount = Math.max(2, Math.ceil(RARITIES[car.rarity].scrap / 3));
    this.state.blueprints[carId] = count - 1;
    if (this.state.blueprints[carId] <= 0) delete this.state.blueprints[carId];
    this.state.scraps += amount;
    this.save(true);
    this.emit('vault', { car, amount });
    return { ok: true, amount };
  }

  // ── Wheel ────────────────────────────────────────────────────────────────
  freeSpinReady() {
    return Date.now() - (this.state.wheel.lastFree || 0) >= FREE_SPIN_MS;
  }
  freeSpinRemaining() {
    return Math.max(0, FREE_SPIN_MS - (Date.now() - (this.state.wheel.lastFree || 0)));
  }
  spin(useFree) {
    const free = Boolean(useFree && this.freeSpinReady());
    const cost = free ? 0 : WHEEL_COST;
    if (this.state.credits < cost) return { ok: false, reason: 'Not enough credits.' };
    this.state.credits -= cost;
    const now = Date.now();
    if (free) this.state.wheel.lastFree = now;
    this.state.wheel.lastSpin = now;
    const index = Math.floor(Math.random() * WHEEL_REWARDS.length);
    this.save(true);
    this.emit('spinStart', { index, free, cost });
    return { ok: true, index, reward: WHEEL_REWARDS[index], free, cost };
  }

  grantWheelReward(reward) {
    const result = { credits: 0, scraps: 0, core: 0, blueprint: null };
    const godly = this.selectedCar()?.trait === 'godly';
    if (reward.kind === 'credits') {
      result.credits = Math.round(reward.amount * (godly ? 1.05 : 1));
      this.state.credits += result.credits;
    } else if (reward.kind === 'scrap') {
      result.scraps = reward.amount;
      this.state.scraps += reward.amount;
    } else if (reward.kind === 'core') {
      result.core = reward.amount;
      this.state.fusionCores += reward.amount;
    } else if (reward.kind === 'blueprint') {
      const ids = Object.keys(this.state.owned);
      if (ids.length) {
        const id = ids[Math.floor(Math.random() * ids.length)];
        this.state.blueprints[id] = this.blueprintCount(id) + reward.amount;
        result.blueprint = CARS_BY_ID[id];
      } else {
        result.credits = 60;
        this.state.credits += 60;
      }
    }
    this.save(true);
    this.emit('wheelReward', result);
    return result;
  }

  // ── Offline income ───────────────────────────────────────────────────────
  accrueOffline(minutes) {
    if (!Number.isFinite(minutes) || minutes <= 0) return;
    this.state.pendingOffline = clamp(this.state.pendingOffline + minutes * this.passiveRate(), 0, this.offlineCap());
    this.save(true);
  }
  collectOffline() {
    const amount = this.offlinePending();
    if (amount < 1) return { ok: false, reason: 'Nothing to collect yet.' };
    this.state.credits += amount;
    this.state.pendingOffline = 0;
    this.save(true);
    this.emit('offlineCollect', { amount });
    return { ok: true, amount };
  }

  // ── Races ────────────────────────────────────────────────────────────────
  finishRace(trackId, placement, time) {
    const track = TRACKS_BY_ID[trackId];
    if (!track) return null;
    placement = clamp(int(placement, 1, 1, 3), 1, 3);
    time = num(time, 999, 0.1, 9999);
    const car = this.selectedCar();
    const hacker = car?.trait === 'hacker';
    const placeMult = placement === 1 ? 1 : placement === 2 ? 0.62 : 0.38;
    let credits = Math.round((track.reward * placeMult * (hacker ? 1.1 : 1)) / 5) * 5;
    let firstWinBonus = 0;
    const prevBest = this.state.races[trackId];
    if (placement === 1 && !prevBest) {
      firstWinBonus = 40;
      credits += firstWinBonus;
    }
    if (!prevBest || time < prevBest) this.state.races[trackId] = Math.round(time * 100) / 100;
    this.state.credits += credits;
    const scraps = placement === 1 ? 8 : placement === 2 ? 4 : 2;
    this.state.scraps += scraps;
    this.state.stats.races += 1;
    if (placement === 1) this.state.stats.wins += 1;

    let blueprintCar = null;
    const bpChance = placement === 1 ? 0.55 : placement === 2 ? 0.28 : 0.1;
    if (Math.random() < bpChance) {
      const ids = Object.keys(this.state.owned);
      if (ids.length) {
        const id = ids[Math.floor(Math.random() * ids.length)];
        this.state.blueprints[id] = this.blueprintCount(id) + 1;
        blueprintCar = CARS_BY_ID[id];
      }
    }
    this.save(true);
    this.emit('raceFinish', { placement, credits, scraps, blueprintCar, track });
    return { credits, scraps, blueprintCar, firstWinBonus, best: this.state.races[trackId] };
  }
}

export const store = new Store();
export { SAVE_KEY, MAX_LEVEL, TRAITS };

import * as THREE from 'three';
import { RARITIES, TRAITS, carSvg, parseHex, rgba, lighten, darken } from './data.js';

const FONT = '"SF Pro Display",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif';
const textures = new Map();

function canvas(w, h) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  return c;
}
function tex(c, srgb = true) {
  const t = new THREE.CanvasTexture(c);
  if (srgb) t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  return t;
}
export function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}
function fitFont(ctx, text, maxWidth, startSize, weight = 900, family = FONT) {
  let size = startSize;
  do {
    ctx.font = `${weight} ${size}px ${family}`;
    if (ctx.measureText(text).width <= maxWidth) break;
    size -= 1;
  } while (size > 10);
  return size;
}
function wrapLines(ctx, text, maxWidth, maxLines = 3) {
  const words = String(text).toUpperCase().split(/\s+/);
  const lines = [];
  let line = '';
  for (const word of words) {
    const test = line ? line + ' ' + word : word;
    if (ctx.measureText(test).width > maxWidth && line) {
      lines.push(line);
      line = word;
      if (lines.length >= maxLines - 1) break;
    } else line = test;
  }
  if (line && lines.length < maxLines) lines.push(line);
  return lines;
}

export function drawCarSide(ctx, car, x, y, scale = 1) {
  const rar = RARITIES[car.rarity] || RARITIES.street;
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(scale, scale);

  // ground shadow
  const sg = ctx.createRadialGradient(62, 44, 3, 62, 44, 48);
  sg.addColorStop(0, 'rgba(0,0,0,.55)');
  sg.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = sg;
  ctx.beginPath(); ctx.ellipse(62, 43, 48, 5, 0, 0, Math.PI * 2); ctx.fill();

  const bodyGrad = ctx.createLinearGradient(0, 12, 0, 42);
  bodyGrad.addColorStop(0, lighten(car.color, 0.52));
  bodyGrad.addColorStop(0.32, car.color);
  bodyGrad.addColorStop(0.78, darken(car.color, 0.18));
  bodyGrad.addColorStop(1, darken(car.color, 0.55));

  ctx.beginPath();
  ctx.moveTo(12, 33);
  ctx.quadraticCurveTo(12, 27, 20, 27);
  ctx.lineTo(27, 26);
  ctx.lineTo(37, 17);
  ctx.quadraticCurveTo(41, 13, 48, 13);
  ctx.lineTo(64, 13);
  ctx.quadraticCurveTo(71, 13, 76, 17);
  ctx.lineTo(82, 24);
  ctx.lineTo(97, 27);
  ctx.quadraticCurveTo(104, 28, 106, 32);
  ctx.lineTo(106, 36);
  ctx.quadraticCurveTo(106, 39, 102, 39);
  ctx.lineTo(16, 39);
  ctx.quadraticCurveTo(12, 39, 12, 33);
  ctx.closePath();
  ctx.fillStyle = bodyGrad;
  ctx.fill();
  ctx.lineWidth = 0.8;
  ctx.strokeStyle = `rgba(255,255,255,.38)`;
  ctx.stroke();

  // windows
  ctx.beginPath();
  ctx.moveTo(38, 25);
  ctx.lineTo(45, 17);
  ctx.quadraticCurveTo(47, 15, 51, 15);
  ctx.lineTo(63, 15);
  ctx.quadraticCurveTo(68, 15, 71, 18);
  ctx.lineTo(75, 24);
  ctx.closePath();
  const gg = ctx.createLinearGradient(38, 15, 76, 25);
  gg.addColorStop(0, 'rgba(155,215,255,.32)');
  gg.addColorStop(0.5, 'rgba(7,14,26,.96)');
  gg.addColorStop(1, 'rgba(90,150,220,.18)');
  ctx.fillStyle = gg; ctx.fill();

  // window split + highlight
  ctx.strokeStyle = 'rgba(190,225,255,.24)';
  ctx.lineWidth = 0.7;
  ctx.beginPath(); ctx.moveTo(57, 15); ctx.lineTo(57, 24.4); ctx.stroke();
  ctx.strokeStyle = 'rgba(255,255,255,.4)';
  ctx.beginPath(); ctx.moveTo(15, 29); ctx.lineTo(103, 29); ctx.stroke();

  // side vent + door
  ctx.strokeStyle = 'rgba(0,0,0,.35)'; ctx.lineWidth = 0.7;
  ctx.beginPath(); ctx.moveTo(48, 27); ctx.lineTo(48, 37); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(64, 27); ctx.lineTo(64, 37); ctx.stroke();

  // rarity side trim
  ctx.strokeStyle = rar.color;
  ctx.lineWidth = 1.1;
  ctx.shadowColor = rar.color; ctx.shadowBlur = 4;
  ctx.beginPath(); ctx.moveTo(20, 35.6); ctx.lineTo(38, 35.6); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(86, 35.6); ctx.lineTo(101, 35.6); ctx.stroke();
  ctx.shadowBlur = 0;

  // wheels
  for (const cx of [32, 90]) {
    ctx.beginPath(); ctx.arc(cx, 36, 8.6, 0, Math.PI * 2);
    ctx.fillStyle = '#06090f'; ctx.fill();
    ctx.lineWidth = 1.1; ctx.strokeStyle = 'rgba(205,220,240,.25)'; ctx.stroke();
    ctx.beginPath(); ctx.arc(cx, 36, 4.6, 0, Math.PI * 2);
    ctx.fillStyle = '#111826'; ctx.fill();
    ctx.lineWidth = 1.1; ctx.strokeStyle = rar.color; ctx.stroke();
    ctx.beginPath(); ctx.arc(cx, 36, 1.5, 0, Math.PI * 2);
    ctx.fillStyle = '#d8e6f7'; ctx.fill();
  }

  // lights
  ctx.fillStyle = '#fff3c8';
  ctx.shadowColor = '#ffe8ad'; ctx.shadowBlur = 8;
  ctx.fillRect(103, 29.5, 3.2, 2.3);
  ctx.shadowBlur = 0;
  ctx.fillStyle = '#ff4b74';
  ctx.shadowColor = '#ff2a55'; ctx.shadowBlur = 7;
  ctx.fillRect(12.4, 31, 2.3, 1.8);
  ctx.shadowBlur = 0;

  // gloss streak
  ctx.beginPath();
  ctx.moveTo(24, 22);
  ctx.lineTo(54, 17);
  ctx.lineTo(46, 20);
  ctx.lineTo(26, 25);
  ctx.closePath();
  ctx.fillStyle = 'rgba(255,255,255,.28)';
  ctx.fill();
  ctx.restore();
}

export function makeCardTexture(car) {
  const key = `card:${car.id}`;
  if (textures.has(key)) return textures.get(key);
  const rar = RARITIES[car.rarity];
  const trait = car.trait ? TRAITS[car.trait] : null;
  const W = 512, H = 720;
  const c = canvas(W, H), ctx = c.getContext('2d');

  ctx.fillStyle = '#060910';
  ctx.fillRect(0, 0, W, H);
  const bg = ctx.createLinearGradient(0, 0, W, H);
  bg.addColorStop(0, '#121a2a');
  bg.addColorStop(0.35, '#090d16');
  bg.addColorStop(1, '#04060b');
  ctx.fillStyle = bg; ctx.fillRect(0, 0, W, H);

  // rarity aura
  const aura = ctx.createRadialGradient(256, 140, 0, 256, 140, 330);
  aura.addColorStop(0, rgba(rar.color, 0.34));
  aura.addColorStop(0.45, rgba(rar.color, 0.1));
  aura.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = aura; ctx.fillRect(0, 0, W, H);

  // micro grid
  ctx.strokeStyle = 'rgba(255,255,255,.028)';
  ctx.lineWidth = 1;
  for (let x = 0; x <= W; x += 32) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, H); ctx.stroke(); }
  for (let y = 0; y <= H; y += 32) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke(); }

  // diagonal foil streaks
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  for (let i = -2; i < 8; i++) {
    const g = ctx.createLinearGradient(0, i * 110, 320, i * 110 + 180);
    g.addColorStop(0, 'rgba(0,0,0,0)');
    g.addColorStop(0.5, i % 3 === 0 ? 'rgba(255,255,255,.05)' : 'rgba(120,220,255,.035)');
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g;
    ctx.save(); ctx.translate(0, i * 120); ctx.rotate(-0.46);
    ctx.fillRect(-100, -30, 800, 34); ctx.restore();
  }
  ctx.restore();

  // frame
  const frame = ctx.createLinearGradient(0, 0, W, H);
  frame.addColorStop(0, rar.color);
  frame.addColorStop(0.5, 'rgba(255,255,255,.5)');
  frame.addColorStop(1, rar.color);
  ctx.strokeStyle = frame;
  ctx.lineWidth = 4;
  roundRect(ctx, 10, 10, W - 20, H - 20, 22); ctx.stroke();
  ctx.strokeStyle = 'rgba(255,255,255,.12)';
  ctx.lineWidth = 1;
  roundRect(ctx, 19, 19, W - 38, H - 38, 16); ctx.stroke();

  // header
  ctx.fillStyle = '#f2f7ff';
  ctx.font = `900 22px ${FONT}`;
  ctx.fillText('APEX', 34, 56);
  const apexW = ctx.measureText('APEX').width;
  ctx.fillStyle = '#ff3d86';
  ctx.fillText('//RIP', 34 + apexW, 56);
  ctx.font = `800 11px ${FONT}`;
  ctx.fillStyle = 'rgba(190,205,230,.55)';
  ctx.textAlign = 'right';
  ctx.fillText('SERIES 02', W - 36, 48);
  ctx.fillText('TRADING CARD', W - 36, 63);
  ctx.textAlign = 'left';
  ctx.strokeStyle = 'rgba(255,255,255,.15)';
  ctx.beginPath(); ctx.moveTo(34, 78); ctx.lineTo(W - 34, 78); ctx.stroke();

  // rarity
  ctx.font = `800 10px ${FONT}`;
  ctx.fillStyle = 'rgba(190,205,230,.55)';
  ctx.fillText('RARITY TIER', 36, 105);
  ctx.font = `900 34px ${FONT}`;
  ctx.fillStyle = rar.color;
  ctx.shadowColor = rgba(rar.color, 0.7); ctx.shadowBlur = 16;
  ctx.fillText(rar.name.toUpperCase(), 34, 140);
  ctx.shadowBlur = 0;
  ctx.fillStyle = rar.color;
  ctx.fillRect(36, 152, 54, 3);
  ctx.fillStyle = 'rgba(255,255,255,.2)';
  ctx.fillRect(94, 152, W - 130, 1);

  // car art
  ctx.save();
  ctx.globalAlpha = 0.95;
  drawCarSide(ctx, car, 58, 200, 3.32);
  ctx.restore();
  const floor = ctx.createLinearGradient(0, 352, 0, 376);
  floor.addColorStop(0, rgba(rar.color, 0.2));
  floor.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = floor; ctx.fillRect(40, 352, W - 80, 34);

  // name
  ctx.font = `900 38px ${FONT}`;
  const nameSize = fitFont(ctx, car.name.toUpperCase(), W - 72, 38, 900);
  ctx.font = `900 ${nameSize}px ${FONT}`;
  ctx.fillStyle = '#f6f9ff';
  ctx.fillText(car.name.toUpperCase(), 36, 420);

  // trait or stock
  if (trait) {
    ctx.font = `900 12px ${FONT}`;
    const tw = ctx.measureText(trait.name.toUpperCase()).width + 44;
    roundRect(ctx, 36, 440, tw, 30, 8);
    ctx.fillStyle = rgba(trait.color, 0.16); ctx.fill();
    ctx.strokeStyle = rgba(trait.color, 0.5); ctx.lineWidth = 1.2; ctx.stroke();
    ctx.beginPath(); ctx.arc(49, 455, 4, 0, Math.PI * 2);
    ctx.fillStyle = trait.color; ctx.shadowColor = trait.color; ctx.shadowBlur = 8; ctx.fill(); ctx.shadowBlur = 0;
    ctx.fillStyle = trait.color;
    ctx.fillText(trait.name.toUpperCase(), 59, 459);
    ctx.font = `700 9px ${FONT}`;
    ctx.fillStyle = 'rgba(220,232,250,.55)';
    ctx.fillText(trait.perk, 36 + tw + 10, 459);
  } else {
    ctx.font = `800 11px ${FONT}`;
    ctx.fillStyle = 'rgba(190,205,230,.4)';
    ctx.fillText('NO SIGNATURE TRAIT', 36, 458);
  }

  // stats
  const stats = [
    ['SPEED', car.speed, '#4fe3ff'],
    ['ACCEL', car.accel, '#ff9d3d'],
    ['GRIP', car.grip, '#43ffa3'],
  ];
  stats.forEach(([label, value, color], i) => {
    const y = 500 + i * 40;
    ctx.font = `800 11px ${FONT}`;
    ctx.fillStyle = 'rgba(200,214,238,.62)';
    ctx.fillText(label, 38, y);
    const bx = 116, bw = 308;
    ctx.fillStyle = 'rgba(255,255,255,.09)';
    roundRect(ctx, bx, y - 9, bw, 7, 4); ctx.fill();
    const grad = ctx.createLinearGradient(bx, 0, bx + bw, 0);
    grad.addColorStop(0, color);
    grad.addColorStop(1, lighten(color, 0.35));
    ctx.fillStyle = grad;
    roundRect(ctx, bx, y - 9, bw * (Math.min(100, value) / 100), 7, 4); ctx.fill();
    ctx.font = `900 12px ${FONT}`;
    ctx.fillStyle = '#eef4ff';
    ctx.textAlign = 'right';
    ctx.fillText(String(Math.round(value)), W - 38, y);
    ctx.textAlign = 'left';
  });

  // footer
  ctx.strokeStyle = 'rgba(255,255,255,.13)';
  ctx.beginPath(); ctx.moveTo(34, 632); ctx.lineTo(W - 34, 632); ctx.stroke();
  ctx.font = `800 10px ${FONT}`;
  ctx.fillStyle = 'rgba(185,205,232,.5)';
  ctx.fillText('APEX//RIP · AUTHENTIC DROP', 36, 656);
  ctx.textAlign = 'right';
  ctx.fillStyle = rar.color;
  ctx.fillText(`N° ${String(hashCode(car.id) % 9999).padStart(4, '0')} / ${rar.short}`, W - 36, 656);
  ctx.textAlign = 'left';

  ctx.fillStyle = rgba(rar.color, 0.7);
  ctx.fillRect(34, 674, W - 68, 2);

  // final glass sheen
  const sheen = ctx.createLinearGradient(0, 0, W, H);
  sheen.addColorStop(0, 'rgba(255,255,255,.08)');
  sheen.addColorStop(0.16, 'rgba(255,255,255,.01)');
  sheen.addColorStop(0.5, 'rgba(255,255,255,0)');
  ctx.fillStyle = sheen; ctx.fillRect(0, 0, W, H);

  const texture = tex(c);
  textures.set(key, texture);
  return texture;
}

export function makeCardBackTexture() {
  const key = 'card:back';
  if (textures.has(key)) return textures.get(key);
  const W = 512, H = 720;
  const c = canvas(W, H), ctx = c.getContext('2d');
  const g = ctx.createLinearGradient(0, 0, W, H);
  g.addColorStop(0, '#111a2b'); g.addColorStop(0.5, '#080b14'); g.addColorStop(1, '#0c1422');
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'rgba(255,255,255,.035)';
  for (let i = 0; i < 30; i++) {
    ctx.beginPath(); ctx.moveTo(0, i * 26); ctx.lineTo(W, i * 26); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(i * 22, 0); ctx.lineTo(i * 22, H); ctx.stroke();
  }
  ctx.save();
  ctx.translate(W / 2, H / 2);
  ctx.rotate(-0.5);
  ctx.strokeStyle = 'rgba(79,227,255,.16)';
  ctx.lineWidth = 2;
  for (let i = 0; i < 5; i++) {
    ctx.beginPath(); ctx.arc(0, 0, 90 + i * 42, 0, Math.PI * 2); ctx.stroke();
  }
  ctx.restore();
  ctx.strokeStyle = 'rgba(255,255,255,.18)'; ctx.lineWidth = 3;
  roundRect(ctx, 12, 12, W - 24, H - 24, 22); ctx.stroke();
  ctx.textAlign = 'center';
  ctx.font = `900 52px ${FONT}`;
  ctx.fillStyle = '#f2f7ff';
  ctx.fillText('APEX', W / 2, H / 2 - 10);
  ctx.fillStyle = '#ff3d86';
  ctx.fillText('//RIP', W / 2, H / 2 + 44);
  ctx.font = `800 12px ${FONT}`;
  ctx.fillStyle = 'rgba(180,205,230,.45)';
  ctx.fillText('SEALED · AUTHENTIC · GLOSSY', W / 2, H / 2 + 88);
  ctx.textAlign = 'left';
  const t = tex(c);
  textures.set(key, t);
  return t;
}

export function makePackTexture(pack) {
  const key = `pack:${pack.id}`;
  if (textures.has(key)) return textures.get(key);
  const W = 512, H = 768;
  const c = canvas(W, H), ctx = c.getContext('2d');
  const g = ctx.createLinearGradient(0, 0, W, H);
  g.addColorStop(0, darken(pack.color2, 0.25));
  g.addColorStop(0.45, pack.color2);
  g.addColorStop(1, '#04060b');
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);

  const aura = ctx.createRadialGradient(W * 0.78, H * 0.16, 0, W * 0.78, H * 0.16, 430);
  aura.addColorStop(0, rgba(pack.color, 0.55));
  aura.addColorStop(0.35, rgba(pack.color, 0.16));
  aura.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = aura; ctx.fillRect(0, 0, W, H);

  // circuit traces
  ctx.strokeStyle = rgba(pack.color, 0.2);
  ctx.lineWidth = 1.2;
  for (let i = 0; i < 7; i++) {
    ctx.beginPath();
    let x = 0, y = 120 + i * 82;
    ctx.moveTo(x, y);
    for (let j = 0; j < 5; j++) {
      x += 70 + (i % 3) * 20;
      y += ((i + j) % 2 ? 26 : -26);
      ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
  ctx.strokeStyle = 'rgba(255,255,255,.035)';
  for (let i = 0; i < 22; i++) { ctx.beginPath(); ctx.moveTo(i * 26, 0); ctx.lineTo(i * 26, H); ctx.stroke(); }

  // big ghost glyph
  ctx.save();
  ctx.translate(W / 2, H * 0.64);
  ctx.rotate(-0.14);
  ctx.textAlign = 'center';
  ctx.font = `900 260px ${FONT}`;
  ctx.fillStyle = 'rgba(255,255,255,.035)';
  ctx.fillText(pack.name.split(' ')[0].slice(0, 1), 0, 60);
  ctx.restore();

  // header
  ctx.fillStyle = '#f4f8ff';
  ctx.font = `900 24px ${FONT}`;
  ctx.fillText('APEX', 36, 58);
  const aw = ctx.measureText('APEX').width;
  ctx.fillStyle = '#ff3d86';
  ctx.fillText('//RIP', 36 + aw, 58);
  ctx.font = `800 11px ${FONT}`;
  ctx.fillStyle = 'rgba(225,238,255,.6)';
  ctx.textAlign = 'right';
  ctx.fillText('SEALED DROP', W - 36, 44);
  ctx.fillText(pack.tier, W - 36, 60);
  ctx.textAlign = 'left';
  ctx.strokeStyle = rgba(pack.color, 0.6);
  ctx.beginPath(); ctx.moveTo(36, 82); ctx.lineTo(W - 36, 82); ctx.stroke();

  // title
  ctx.font = `900 55px ${FONT}`;
  const lines = wrapLines(ctx, pack.name, W - 90, 2);
  ctx.fillStyle = '#ffffff';
  ctx.shadowColor = rgba(pack.color, 0.6); ctx.shadowBlur = 22;
  let ty = 178;
  for (const line of lines) {
    const sz = fitFont(ctx, line, W - 80, 55, 900);
    ctx.font = `900 ${sz}px ${FONT}`;
    ctx.fillText(line, 38, ty);
    ty += sz * 1.02;
  }
  ctx.shadowBlur = 0;

  // tagline
  ctx.font = `900 15px ${FONT}`;
  ctx.fillStyle = pack.color;
  ctx.fillText(pack.tag, 40, ty + 6);
  ctx.fillStyle = rgba(pack.color, 0.35);
  ctx.fillRect(40, ty + 17, 160, 2);

  // feature car silhouette
  const car = pack.focus && pack.focus[0];
  if (car) {
    ctx.save();
    ctx.globalAlpha = 0.9;
    drawCarSide(ctx, { id: car, name: car, color: pack.color, rarity: 'apex' }, 42, 432, 3.5);
    ctx.restore();
  }

  // rarity bar
  ctx.font = `800 10px ${FONT}`;
  ctx.fillStyle = 'rgba(220,235,255,.5)';
  ctx.fillText('PULL ODDS', 38, 540);
  let x = 38;
  const rarNames = ['STK', 'STR', 'PRO', 'PRT', 'APX'];
  pack.odds.forEach((odd, i) => {
    const w = 88;
    ctx.fillStyle = 'rgba(255,255,255,.07)';
    roundRect(ctx, x, 552, w - 6, 8, 3); ctx.fill();
    const col = ['#aab5c5', '#35e6ac', '#4fa6ff', '#b47bff', '#ffc247'][i];
    ctx.fillStyle = col;
    roundRect(ctx, x, 552, Math.max(2, (w - 6) * (odd / 100) * 1.8), 8, 3); ctx.fill();
    ctx.fillStyle = 'rgba(220,235,255,.55)';
    ctx.fillText(`${rarNames[i]} ${odd}%`, x, 578);
    x += w;
  });

  // footer
  ctx.strokeStyle = 'rgba(255,255,255,.15)';
  ctx.beginPath(); ctx.moveTo(36, 624); ctx.lineTo(W - 36, 624); ctx.stroke();
  ctx.font = `900 17px ${FONT}`;
  ctx.fillStyle = '#f2f7ff';
  ctx.fillText('5 RARITIES', 38, 660);
  ctx.font = `800 10px ${FONT}`;
  ctx.fillStyle = 'rgba(220,235,255,.5)';
  ctx.fillText('SIGNATURE TRAITS · GLOSS SERIES', 38, 680);
  ctx.textAlign = 'right';
  ctx.fillStyle = pack.color;
  ctx.font = `900 13px ${FONT}`;
  ctx.fillText('DO NOT BEND', W - 38, 660);
  ctx.textAlign = 'left';

  // gloss
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  const gl = ctx.createLinearGradient(0, 0, W, 200);
  gl.addColorStop(0, 'rgba(255,255,255,0)');
  gl.addColorStop(0.4, 'rgba(255,255,255,.1)');
  gl.addColorStop(0.5, 'rgba(255,255,255,.2)');
  gl.addColorStop(0.6, 'rgba(255,255,255,.04)');
  gl.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = gl;
  ctx.save(); ctx.rotate(-0.5); ctx.translate(-200, 100); ctx.fillRect(0, 0, 900, 150); ctx.restore();
  ctx.restore();

  // frame
  const fr = ctx.createLinearGradient(0, 0, W, H);
  fr.addColorStop(0, pack.color);
  fr.addColorStop(0.5, 'rgba(255,255,255,.45)');
  fr.addColorStop(1, pack.color);
  ctx.strokeStyle = fr; ctx.lineWidth = 4;
  roundRect(ctx, 10, 10, W - 20, H - 20, 20); ctx.stroke();
  ctx.strokeStyle = 'rgba(255,255,255,.1)'; ctx.lineWidth = 1;
  roundRect(ctx, 18, 18, W - 36, H - 36, 14); ctx.stroke();

  const t = tex(c);
  textures.set(key, t);
  return t;
}

