_buildWheel() {
  const g = this.groups.wheel;
  g.add(this._makeBackdrop(17, 13, 4.5, 0x07060e));
  g.add(this._makeFloor(15, 0, 0x07070f));
  for (const [x, color] of [[-5.6, 0x4fe3ff], [5.6, 0xff3d86]]) {
