const base = 'http://127.0.0.1:9222';
const sleep = ms => new Promise(r => setTimeout(r, ms));
const r = await fetch(`${base}/json/new?http://127.0.0.1:8099/`, { method: 'PUT' });
const target = await r.json();
const ws = new WebSocket(target.webSocketDebuggerUrl);
let id = 0; const pending = new Map();
ws.onmessage = ev => { const m = JSON.parse(ev.data); if (m.id && pending.has(m.id)) { const p = pending.get(m.id); pending.delete(m.id); m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result); } };
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
const send = (method, params = {}) => new Promise((resolve, reject) => { const mid = ++id; pending.set(mid, { resolve, reject }); ws.send(JSON.stringify({ id: mid, method, params })); });
const ev = async expression => { const x = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true }); if (x.exceptionDetails) throw new Error(x.exceptionDetails.exception?.description || x.exceptionDetails.text); return x.result.value; };
await send('Runtime.enable');
await send('Page.enable');
await send('Page.bringToFront');
await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
for (let i = 0; i < 40; i++) {
  if (await ev('!!(window.__apex && window.__apex.world && window.__apex.world.rip.pack)')) break;
  await sleep(250);
}
const snap = () => ev(`(() => {
  const p = window.__apex.world.rip.pack;
  const b = p.userData.body;
  return { t: window.__apex.world.time, y: b.rotation.y, x: b.rotation.x, bob: p.position.y, visible: p.visible };
})()`);
const a = await snap();
await sleep(2000);
const b = await snap();
const shot = await send('Page.captureScreenshot', { format: 'jpeg', quality: 82 });
const fs = await import('node:fs');
fs.writeFileSync('/home/runner/work/PlayGround/PlayGround/screenshots/pack-spin.jpg', Buffer.from(shot.data, 'base64'));
await sleep(2000);
const c = await snap();
console.log(JSON.stringify({ a, b, c, delta1: b.y - a.y, delta2: c.y - b.y, tiltChanged: a.x !== b.x, bobChanged: a.bob !== b.bob }, null, 2));
ws.close();

