  const r = 4 + (i%9)*0.9; const a = seed[i] + t*(0.08 + (i%5)*0.02);
  pos[x] = Math.cos(a)*r;
  pos[z] = -3 + Math.sin(a)*r*0.65;
  pos[y] = 1.2 + Math.sin(t*0.3+seed[i]*3)*2.2 + (i%7)*0.5;
