import fs from 'node:fs';

const BASE = 'http://localhost:9515';
let SID = '';
const log = [];
function note(msg, data) { log.push({ msg, data }); console.log(msg, data === undefined ? '' : JSON.stringify(data)); }

async function req(method, path, body) {
  const res = await fetch(BASE + path, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body ? JSON.stringify(body) : undefined,
  });
  const json = await res.json();
  if (!res.ok || (json.value && json.value.error)) {
    throw new Error(`${method} ${path} failed: ${JSON.stringify(json).slice(0, 800)}`);
  }
  return json.value;
}

async function js(script, ...args) {
  return req('POST', `/session/${SID}/execute/sync`, { script, args });
}
async function shot(name) {
  const b64 = await req('GET', `/session/${SID}/screenshot`);
  fs.writeFileSync(`/tmp/opencode/${name}.png`, Buffer.from(b64, 'base64'));
  note('screenshot', name);
}
async function click(sel) {
  const ok = await js(`const el=document.querySelector(arguments[0]); if(!el) return false; el.click(); return true;`, sel);
  if (!ok) throw new Error('missing element ' + sel);
  await new Promise(r => setTimeout(r, 350));
}
async function waitFor(fn, label, ms = 12000) {
  const start = Date.now();
  while (Date.now() - start < ms) {
    if (await js(fn)) return true;
    await new Promise(r => setTimeout(r, 200));
  }
  throw new Error('timeout waiting for ' + label);
}
async function state() {
  return js(`return {
    menuHidden: document.getElementById('feature-menu').hidden,
    sheetTitle: document.querySelector('#sheet-title')?.textContent || null,
    sheetOpen: !document.getElementById('sheet-layer').hidden,
    credits: document.getElementById('hud-credits')?.textContent,
    tab: document.querySelector('.tab.active')?.dataset.tab,
    rows: document.querySelectorAll('.shop-row').length,
    shopHead: document.querySelector('.shop-head b')?.textContent || null,
    errors: window.__errs || null,
  };`);
}

try {
  const cap = await req('POST', '/session', {
    capabilities: { alwaysMatch: {
      browserName: 'chrome',
      'goog:chromeOptions': {
        args: ['--headless=new', '--no-sandbox', '--disable-gpu', '--enable-unsafe-swiftshader', '--use-angle=swiftshader', '--window-size=390,844'],
        mobileEmulation: { deviceMetrics: { width: 390, height: 844, pixelRatio: 1 } },
      },
      'goog:loggingPrefs': { browser: 'ALL' },
    } },
  });
  SID = cap.sessionId;
  note('session', SID);
  await req('POST', `/session/${SID}/url`, { url: 'http://localhost:8765/index.html' });
  await waitFor(`return document.getElementById('boot')?.classList.contains('done') === true;`, 'boot done');
  await js(`window.__errs=[]; addEventListener('error',e=>window.__errs.push(String(e.message))); addEventListener('unhandledrejection',e=>window.__errs.push(String(e.reason))); return true;`);
  await new Promise(r => setTimeout(r, 600));
  note('initial', await state());

  // 1. Feature menu
  await click('#feature-btn');
  await new Promise(r => setTimeout(r, 250));
  note('menu open', await state());
  await shot('flow-menu');

  // 2. Starter pack rip to get a car
  await click('[data-feature="weather"]');
  await new Promise(r => setTimeout(r, 300));
  note('weather shop', await state());
  await shot('flow-weather');
  await click('[data-sheet-action="weather-buy"][data-id="neon-rain"]');
