import fs from 'node:fs';
const BASE='http://localhost:9515';let SID='';
const req=async(m,p,b)=>{const r=await fetch(BASE+p,{method:m,headers:{'Content-Type':'application/json'},body:b?JSON.stringify(b):undefined});const j=await r.json();if(!r.ok||(j.value&&j.value.error))throw new Error(JSON.stringify(j).slice(0,600));return j.value;};
const js=(s,...a)=>req('POST',`/session/${SID}/execute/sync`,{script:s,args:a});
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
try{
 const cap=await req('POST','/session',{capabilities:{alwaysMatch:{browserName:'chrome','goog:chromeOptions':{args:['--headless=new','--no-sandbox','--disable-gpu','--enable-unsafe-swiftshader','--use-angle=swiftshader'],mobileEmulation:{deviceMetrics:{width:390,height:844,pixelRatio:1}}},'goog:loggingPrefs':{browser:'ALL'}}}});
 SID=cap.sessionId;
 await req('POST',`/session/${SID}/url`,{url:'http://localhost:8765/index.html'});
 for(let i=0;i<60;i++){if(await js(`return !!window.__apex && document.getElementById('app')?.classList.contains('ready')`))break;await sleep(200);}
 await js(`window.__errs=[]; addEventListener('error',e=>window.__errs.push(String(e.message))); addEventListener('unhandledrejection',e=>window.__errs.push(String(e.reason))); const a=window.__apex; a.ui.setTab('race'); a.ui.startRace(); return true;`);
 for(let i=0;i<40;i++){if(await js(`return window.__apex.race.phase==='running'`))break;await sleep(300);}
 const before=await js(`const a=window.__apex; return {auto:a.store.state.autoRace,label:document.getElementById('auto-race-toggle').innerText,lane:a.race.lane,nitro:+a.race.nitro.toFixed(2)};`);
 const clicked=await js(`document.getElementById('auto-race-toggle').click(); return true;`);
 await sleep(3000);
 const on=await js(`const a=window.__apex; return {auto:a.store.state.autoRace,label:document.getElementById('auto-race-toggle').innerText,pressed:document.getElementById('auto-race-toggle').getAttribute('aria-pressed'),lane:a.race.lane,nitro:+a.race.nitro.toFixed(2),dist:Math.round(a.race.dist)};`);
 await js(`document.getElementById('auto-race-toggle').click(); return true;`);
 await sleep(300);
 const off=await js(`const a=window.__apex; return {auto:a.store.state.autoRace,label:document.getElementById('auto-race-toggle').innerText,pressed:document.getElementById('auto-race-toggle').getAttribute('aria-pressed')};`);
 // manual lane should still work
 const laneBefore=await js(`return window.__apex.race.lane`);
 await js(`document.getElementById('lane-left').click(); document.getElementById('lane-right').click(); return true`);
 await sleep(300);
 const laneAfter=await js(`return window.__apex.race.lane`);
 const logs=await req('POST',`/session/${SID}/log`,{type:'browser'});
 console.log(JSON.stringify({before,on,off,laneBefore,laneAfter,severe:logs.filter(l=>l.level==='SEVERE'),errs:await js(`return window.__errs`)},null,2));
}catch(e){console.error('FAIL',e.message)}finally{if(SID)try{await req('DELETE',`/session/${SID}`)}catch{}}

