+/* weather / theme / cosmetics shops */
+.shop-head{position:relative;display:flex;align-items:center;gap:10px;padding:9px 10px 9px 14px;margin-bottom:10px;border-radius:13px;background:linear-gradient(145deg,rgba(255,255,255,.075),rgba(255,255,255,.018));border:1px solid var(--line-2);overflow:hidden;box-shadow:inset 0 1px 0 rgba(255,255,255,.12)}
+.shop-head::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--sc,var(--cyan));box-shadow:0 0 14px var(--sc,var(--cyan))}
+.shop-head>div{min-width:0;flex:1}
+.shop-head .eyebrow{display:block;margin-bottom:1px}
+.shop-head b{display:block;font-size:13px;font-weight:900;letter-spacing:.01em;text-transform:uppercase;line-height:1.15}
+.shop-head small{display:block;font-size:7.5px;color:var(--muted);line-height:1.4;margin-top:2px}
+.shop-head .pill{flex:0 0 auto;color:#ffe6a3;border-color:rgba(255,194,71,.18);background:rgba(255,194,71,.07)}
+.shop-section{margin-bottom:10px}
+.shop-section>.eyebrow{display:block;margin-bottom:5px}
+.shop-list{display:flex;flex-direction:column;gap:5px}
+.shop-row{display:flex;align-items:center;gap:8px;padding:7px 8px;border-radius:10px;background:rgba(255,255,255,.03);border:1px solid var(--line)}
+.shop-row.active{border-color:var(--sc,var(--cyan));box-shadow:inset 0 0 0 1px var(--sc,var(--cyan)),0 0 16px rgba(0,0,0,.2)}
+.shop-row.locked{opacity:.7}
+.shop-dot{width:8px;height:8px;border-radius:50%;background:var(--sc,var(--cyan));box-shadow:0 0 8px var(--sc,var(--cyan));flex:0 0 auto}
+.shop-copy{min-width:0;flex:1}
+.shop-copy b{display:block;font-size:8.5px;font-weight:900;letter-spacing:.035em;text-transform:uppercase;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
+.shop-copy span{display:block;font-size:6.5px;color:var(--dim);line-height:1.35;margin-top:1px}
+.shop-btn{min-width:54px;height:28px;padding:0 8px;border-radius:7px;font-size:6.5px;font-weight:900;letter-spacing:.05em;background:rgba(255,255,255,.07);border:1px solid var(--line-2);color:#eaf1ff;white-space:nowrap;transition:transform .14s,background .14s}
+.shop-btn.on{background:rgba(67,255,163,.14);border-color:rgba(67,255,163,.38);color:#a8ffd5}
+.shop-btn:disabled{opacity:.45}
+.shop-btn:active{transform:scale(.95)}
+.shop-tag{font-size:6px;font-weight:900;letter-spacing:.1em;color:var(--dim);border:1px dashed var(--line-2);padding:4px 6px;border-radius:5px;white-space:nowrap}
+
+/* car fuse */
+.fuse-stats{display:flex;gap:5px;margin-bottom:8px}
+.fuse-stats span{flex:1;text-align:center;padding:5px 3px;border-radius:7px;background:rgba(255,255,255,.035);border:1px solid var(--line);font-size:6.5px;color:var(--dim);letter-spacing:.08em}
+.fuse-stats b{display:block;font-size:11px;color:#eaf4ff;font-variant-numeric:tabular-nums;margin-top:1px}
+.fuse-cost{display:grid;grid-template-columns:repeat(4,1fr);gap:4px;margin-bottom:8px}
+.fuse-cost span{text-align:center;padding:5px 3px;border-radius:6px;font-size:6.5px;font-weight:800;letter-spacing:.03em;color:#ff9aa0;background:rgba(255,90,99,.07);border:1px solid rgba(255,90,99,.18);white-space:nowrap}
+.fuse-cost span.ok{color:#9dffd0;background:rgba(67,255,163,.08);border-color:rgba(67,255,163,.2)}
+
+/* auto race */
+.race-auto{flex:0 0 64px;gap:3px;padding:0 4px;color:var(--cyan);transition:background .15s,border-color .15s,box-shadow .15s}
+.race-auto span{font-size:6px}
+.race-auto b{font-size:10px;color:var(--dim);letter-spacing:.03em}
+.race-auto.on{background:rgba(79,227,255,.16);border-color:rgba(79,227,255,.5);box-shadow:0 0 16px rgba(79,227,255,.24),inset 0 1px 0 rgba(255,255,255,.16)}
+.race-auto.on b{color:#d6ffff}
+.auto-race-chip{flex:0 0 62px;min-height:46px;border-radius:12px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;background:linear-gradient(160deg,rgba(255,255,255,.09),rgba(255,255,255,.03));border:1px solid var(--line-2);transition:background .15s,border-color .15s,box-shadow .15s}
+.auto-race-chip span{font-size:6.5px;letter-spacing:.13em;font-weight:900;color:var(--dim)}
+.auto-race-chip b{font-size:11px;font-weight:900;color:var(--muted);letter-spacing:.05em}
+.auto-race-chip:active{transform:scale(.96)}
+.auto-race-chip.on{background:linear-gradient(160deg,rgba(79,227,255,.24),rgba(21,119,255,.1));border-color:rgba(79,227,255,.55);box-shadow:0 0 16px rgba(79,227,255,.22),inset 0 1px 0 rgba(255,255,255,.2)}
+.auto-race-chip.on b{color:#d6ffff}
